import{_ as o,a0 as a,w as s,s as r,ao as l,I as i,x as u,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——在Ubuntu中使用音樂軟件“聲破天”Spotify | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——在Ubuntu中使用音樂軟件“聲破天”Spotify | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——在Ubuntu中使用音樂軟件“聲破天”Spotify | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——在Ubuntu中使用音樂軟件“聲破天”Spotify | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Use Spotify In Ubuntu Linux","title":"每日Ubuntu小技巧——在Ubuntu中使用音樂軟件“聲破天”Spotify","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Use Spotify In Ubuntu Linux.md","filePath":"[post].md"}'),b={name:"201402/Daily Ubuntu Tips – Use Spotify In Ubuntu Linux.md"};function d(f,t,y,U,m,T){const n=a("Link");return s(),r("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧——在ubuntu中使用音樂軟件-聲破天-spotify" tabindex="-1">每日Ubuntu小技巧——在Ubuntu中使用音樂軟件“聲破天”Spotify <a class="header-anchor" href="#每日ubuntu小技巧——在ubuntu中使用音樂軟件-聲破天-spotify" aria-label="Permalink to “每日Ubuntu小技巧——在Ubuntu中使用音樂軟件“聲破天”Spotify”">​</a></h1><p>Spotify（譯者注：下面譯為&quot;聲破天&quot;）雲音樂服務已經解除了對所有用户及平台（web端/桌面端/手機端）的時間限制，現在用户可以在任何平台、任何時間無限制地聽免費音樂。</p><p>起初，聲破天有個時間限制，新用户自注冊帳號時起的前六個月可以免費聽音樂，但是這個限制取決於你所在的地區，不過現在所有免費帳號都可以無限制聽音樂。</p><p>任何使用 Ubuntu 桌面客户端聽音樂的用户也沒有了之前對免費賬户聽音樂的限制，Ubuntu 用户可以使用他們最喜歡的桌面操作系統來享受免費音樂。</p><p>如果你現在有點小激動，但是還沒有安裝聲破天，那麼這裏有一個快捷方法來指導你如何在 Ubuntu 上安裝最新版本的聲破天。</p><p>一些地區還不支持聲破天的註冊，這些地區的用户必須得想點別的辦法了（譯者注：需要使用代理），這是因為聲破天並不是所有國家都支持。下面圖片顯示的是目前聲破天支持的國家列表：</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/spotifycountrylist.jpg" alt=""></p><h3 id="在-ubuntu-安裝上聲破天" tabindex="-1">在 Ubuntu 安裝上聲破天 <a class="header-anchor" href="#在-ubuntu-安裝上聲破天" aria-label="Permalink to “在 Ubuntu 安裝上聲破天”">​</a></h3><p>要想在 Ubuntu 上安裝聲破天，需要打開終端然後輸入下面命令，將聲破天的軟件倉庫添加到 Ubuntu</p><pre><code>sudo apt-add-repository -y &quot;deb http://repository.spotify.com stable non-free&quot;
</code></pre><p>下一步，將聲破天的倉庫密鑰添加到 Ubuntu，運行下面命令：</p><pre><code>sudo apt-key adv --keyserver keyserver.ubuntu.com --recv-keys 94558F59
</code></pre><p>最後，更新系統的軟件包倉庫並且安裝聲破天，運行下面命令：</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install spotify-client
</code></pre><p>就這麼簡單！</p><p>在安裝完聲破天后，你需要打開 Ubuntu 的面板，在裏面找到這個軟件。打開後，盡情享受你的免費音樂吧！</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/spotifyclientubuntu.png" alt=""></p><hr>`,18)),i("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-use-spotify-in-ubuntu-linux/"},{default:p(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-use-spotify-in-ubuntu-linux/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=u("譯者：",-1)),e(n,{href:"https://github.com/liuaiping"},{default:p(()=>[...t[2]||(t[2]=[u("liuaiping",-1)])]),_:1}),t[5]||(t[5]=u(" 校對：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[u("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[u("Linux中國",-1)])]),_:1}),t[10]||(t[10]=u(" 榮譽推出",-1))])])}const C=o(b,[["render",d]]);export{w as __pageData,C as default};
